#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

typedef struct { int data[32]; size_t head,size,capacity; } Ring;
static int push(Ring *r,int value){
    if(r->size==r->capacity)return 0;
    r->data[(r->head+r->size)%r->capacity]=value;++r->size;return 1;
}
static int pop(Ring *r,int *out){
    if(!r->size)return 0;
    *out=r->data[r->head];r->head=(r->head+1)%r->capacity;--r->size;return 1;
}
int main(void) {
Ring ring={0};int q;if(scanf("%zu%d",&ring.capacity,&q)!=2||ring.capacity<1||ring.capacity>32||q<0||q>128)return 1;for(int i=0;i<q;++i){char c;int x;if(scanf(" %c",&c)!=1)return 1;if(c=='P'){if(scanf("%d",&x)!=1)return 1;if(!push(&ring,x))puts("ПОЛНО");}else if(c=='O'){if(pop(&ring,&x))printf("%d\n",x);else puts("ПУСТО");}else return 1;}
return 0;
}
